1  int frame_get_lazychunk(blosc2_frame_s *frame, int nchunk, uint8_t **chunk, bool *needs_free) {
     2    int32_t header_len;
     3    int64_t frame_len;
     4    int64_t nbytes;
     5    int64_t cbytes;
     6    int32_t blocksize;
     7    int32_t chunksize;
     8    int32_t nchunks;
     9    int32_t typesize;
    10    int32_t lazychunk_cbytes;
    11    int64_t offset;
    12    FILE* fp = NULL;
    13
    14    *chunk = NULL;
    15    *needs_free = false;
    16    int rc = get_header_info(frame, &header_len, &frame_len, &nbytes, &cbytes,
    17                             &blocksize, &chunksize, &nchunks,
    18                             &typesize, NULL, NULL, NULL, NULL);
    19    if (rc < 0) {
    20      BLOSC_TRACE_ERROR("Unable to get meta info from frame.");
    21      return rc;
    22    }
    23
    24    if (nchunk >= nchunks) {
    25      BLOSC_TRACE_ERROR("nchunk ('%d') exceeds the number of chunks "
    26                        "('%d') in frame.", nchunk, nchunks);
    27      return BLOSC2_ERROR_INVALID_PARAM;
    28    }
    29
    30    // Get the offset to nchunk
    31    rc = get_coffset(frame, header_len, cbytes, nchunk, &offset);
    32    if (rc < 0) {
    33      BLOSC_TRACE_ERROR("Unable to get offset to chunk %d.", nchunk);
    34      return rc;
    35    }
    36
    37    if (offset < 0) {
    38      // Special value
    39      lazychunk_cbytes = BLOSC_EXTENDED_HEADER_LENGTH;
    40      rc = frame_special_chunk(offset, chunksize, typesize, chunk,
    41                               (int32_t)lazychunk_cbytes, needs_free);
    42      goto end;
    43    }
    44
    45    if (frame->cframe == NULL) {
    46      // TODO: make this portable across different endianness
    47      // Get info for building a lazy chunk
    48      int32_t chunk_nbytes;
    49      int32_t chunk_cbytes;
    50      int32_t chunk_blocksize;
    51      uint8_t header[BLOSC_MIN_HEADER_LENGTH];
    52      if (frame->sframe) {
    53        // The chunk is not in the frame
    54        fp = sframe_open_chunk(frame->urlpath, offset, "rb");
    55      }
    56      else {
    57        fp = fopen(frame->urlpath, "rb");
    58        fseek(fp, header_len + offset, SEEK_SET);
    59      }
    60      size_t rbytes = fread(header, 1, BLOSC_MIN_HEADER_LENGTH, fp);
    61      if (rbytes != BLOSC_MIN_HEADER_LENGTH) {
    62        BLOSC_TRACE_ERROR("Cannot read the header for chunk in the frame.");
    63        rc = BLOSC2_ERROR_FILE_READ;
    64        goto end;
    65      }
    66      rc = blosc2_cbuffer_sizes(header, &chunk_nbytes, &chunk_cbytes, &chunk_blocksize);
    67      if (rc < 0) {
    68        goto end;
    69      }
    70      size_t nblocks = chunk_nbytes / chunk_blocksize;
    71      size_t leftover_block = chunk_nbytes % chunk_blocksize;
    72      nblocks = leftover_block ? nblocks + 1 : nblocks;
    73      // Allocate space for the lazy chunk
    74      size_t trailer_len = sizeof(int32_t) + sizeof(int64_t) + nblocks * sizeof(int32_t);
    75      size_t trailer_offset = BLOSC_EXTENDED_HEADER_LENGTH + nblocks * sizeof(int32_t);
    76      lazychunk_cbytes = trailer_offset + trailer_len;
    77      *chunk = malloc(lazychunk_cbytes);
    78      *needs_free = true;
    79
    80      // Read just the full header and bstarts section too (lazy partial length)
    81      if (frame->sframe) {
    82        fseek(fp, 0, SEEK_SET);
    83      }
    84      else {
    85        fseek(fp, header_len + offset, SEEK_SET);
    86      }
    87
    88      rbytes = fread(*chunk, 1, trailer_offset, fp);
    89      if (rbytes != trailer_offset) {
    90        BLOSC_TRACE_ERROR("Cannot read the (lazy) chunk out of the frame.");
    91        rc = BLOSC2_ERROR_FILE_READ;
    92        goto end;
    93      }
    94
    95      // Mark chunk as lazy
    96      uint8_t* blosc2_flags = *chunk + BLOSC2_CHUNK_BLOSC2_FLAGS;
    97      *blosc2_flags |= 0x08U;
    98
    99      // Add the trailer (currently, nchunk + offset + block_csizes)
   100      if (frame->sframe) {
   101        *(int32_t*)(*chunk + trailer_offset) = offset;
   102        *(int64_t*)(*chunk + trailer_offset + sizeof(int32_t)) = offset;
   103      }
   104      else {
   105        *(int32_t*)(*chunk + trailer_offset) = nchunk;
   106        *(int64_t*)(*chunk + trailer_offset + sizeof(int32_t)) = header_len + offset;
   107      }
   108
   109      int32_t* block_csizes = malloc(nblocks * sizeof(int32_t));
   110
   111      int memcpyed = *(*chunk + BLOSC2_CHUNK_FLAGS) & (uint8_t)BLOSC_MEMCPYED;
   112      if (memcpyed) {
   113        // When memcpyed the blocksizes are trivial to compute
   114        for (int i = 0; i < (int)nblocks; i++) {
   115          block_csizes[i] = (int)chunk_blocksize;
   116        }
   117      }
   118      else {
   119        // In regular, compressed chunks, we need to sort the bstarts (they can be out
   120        // of order because of multi-threading), and get a reverse index too.
   121        memcpy(block_csizes, *chunk + BLOSC_EXTENDED_HEADER_LENGTH, nblocks * sizeof(int32_t));
   122        // Helper structure to keep track of original indexes
   123        struct csize_idx *csize_idx = malloc(nblocks * sizeof(struct csize_idx));
   124        for (int n = 0; n < (int)nblocks; n++) {
   125          csize_idx[n].val = block_csizes[n];
   126          csize_idx[n].idx = n;
   127        }
   128        qsort(csize_idx, nblocks, sizeof(struct csize_idx), &sort_offset);
   129        // Compute the actual csizes
   130        int idx;
   131        for (int n = 0; n < (int)nblocks - 1; n++) {
   132          idx = csize_idx[n].idx;
   133          block_csizes[idx] = csize_idx[n + 1].val - csize_idx[n].val;
   134        }
   135        idx = csize_idx[nblocks - 1].idx;
   136        block_csizes[idx] = (int)chunk_cbytes - csize_idx[nblocks - 1].val;
   137        free(csize_idx);
   138      }
   139      // Copy the csizes at the end of the trailer
   140      void *trailer_csizes = *chunk + lazychunk_cbytes - nblocks * sizeof(int32_t);
   141      memcpy(trailer_csizes, block_csizes, nblocks * sizeof(int32_t));
   142      free(block_csizes);
   143    } else {
   144      // The chunk is in memory and just one pointer away
   145      *chunk = frame->cframe + header_len + offset;
   146      if ((int64_t)header_len + offset + BLOSC_MIN_HEADER_LENGTH > frame->len) {
   147        BLOSC_TRACE_ERROR("Cannot read the header for chunk in the (contiguous) frame.");
   148        rc = BLOSC2_ERROR_READ_BUFFER;
   149      } else {
   150        rc = blosc2_cbuffer_sizes(*chunk, NULL, &lazychunk_cbytes, NULL);
   151      }
   152    }
   153
   154    end:
   155    if (fp != NULL) {
   156      fclose(fp);
   157    }
   158    if (rc < 0) {
   159      if (needs_free) {
   160        free(*chunk);
   161        *chunk = NULL;
   162      }
   163      return rc;
   164    }
   165
   166    return (int)lazychunk_cbytes;
   167  }
